 function plant(p){if(p.y<675||p.y>787||ledger.state.grown.length>=18){flash(p);return}const all=[...flowers.map(f=>({x:f.x-32,y:f.y-92,w:64,h:92})),...actors.filter(a=>!['bee','butterfly','fish'].includes(a.id)).map(a=>({x:a.x-a.size*.45,y:a.y-a.size*.83,w:a.size*.9,h:a.size*.74}))];const free=G.core.findSpace(p,{w:60,h:90},all,{x:60,y:650,w:1480,h:147},14);if(!free){flash(p);return}const f={x:free.x,y:free.y+45,kind:['daisy','tulip','poppy','lily'][ledger.state.grown.length%4],id:'grown'+ledger.state.grown.length};ledger.state.grown.push(f);const obj=addFlower(f,f.kind,true,f.id);cue(obj.node);flash(obj.nectar);}
 function obstacles(skip){const boxes=actors.filter(a=>a!==skip&&!['bee','butterfly','fish','bird','owl','woodpecker','sloth'].includes(a.id)).map(a=>({x:a.x-a.size*.43-12,y:a.y-a.size*.87-12,w:a.size*.86+24,h:a.size*.77+24}));if(ledger.current==='asian')boxes.push({x:171,y:190,w:87,h:470},{x:1309,y:190,w:102,h:220},{x:1309,y:510,w:102,h:150},{x:1525,y:240,w:80,h:420});return boxes;}
