  if(a.id==='bear'){const id=[...ledger.state.materials.states].find(([,s])=>s==='ground')?.[0];if(id){a.action={kind:'bear',id,born:now,duration:6500,originalX:a.x};voice(a);return}if(ledger.state.bearLeaf.state==='branch'){const distance=Math.abs(a.x-a.home.x);a.action=distance>2?{kind:'walk',from:a.x,to:a.home.x,born:now,duration:Math.max(500,distance/.04),followUp:'bear-leaf'}:{kind:'bear-leaf',born:now,duration:6800};voice(a);}else a.action={kind:'sniff',born:now,duration:2600};return}
  if(a.id==='peacock'){a.action={kind:'fan',born:now,duration:6000};voice(a);return}
  if(a.id==='tiger'){a.action={kind:'paw-leaf',born:now,duration:3200,leaf:$('tigerPlayLeaf'),leafPoint:{...ledger.state.tigerLeaf},leafTravel:Math.max(0,Math.min(28,a.home.x+112-ledger.state.tigerLeaf.x)),fromX:a.x,toX:Math.min(a.home.x+24,a.x+12)};voice(a);return}
  if(a.id==='hippo'){a.action={kind:'hippo',born:now,duration:3400};ripple({x:a.x,y:701},70);voice(a);return}
  if(a.id==='fish'){a.action={kind:'fish',born:now,duration:4200,from:{x:a.x,y:a.y}};ripple({x:a.x,y:a.y-25});return}
