   if(a.id==='turtle'){a.action={kind:'turtle',born:now,duration:2800,from:a.x,to:a.home.x+(a.x>a.home.x+2?-8:12)};return}
   if(a.id==='zebra'||a.id==='rhino'||a.id==='penguin'){a.action={kind:'walk',born:now,duration:4300,from:a.x,to:a.home.x+(a.x>a.home.x+5?-26:26)};voice(a);return}
