 function hit(p,eventTarget=null){if(eventTarget){if(eventTarget.closest?.('#sun'))return{type:'sun',node:$('sun')};const portal=eventTarget.closest?.('[data-to]');if(portal)return{type:'gate',id:portal.dataset.to,node:portal};const portrait=eventTarget.closest?.('[data-summon]');if(portrait)return{type:'portrait',id:portrait.dataset.summon,node:portrait};const apple=eventTarget.closest?.('[data-apple]');if(apple)return{type:'apple',id:apple.dataset.apple,node:apple};const fig=eventTarget.closest?.('[data-fig]');if(fig)return{type:'fig',id:fig.dataset.fig,node:fig};const figGround=eventTarget.closest?.('[data-fig-ground]');if(figGround)return{type:'figGround',id:figGround.dataset.figGround,node:figGround};const prop=eventTarget.closest?.('[data-prop]');if(prop)return{type:prop.dataset.prop,node:prop};const flower=eventTarget.closest?.('.flower');if(flower){const f=flowers.find(f=>f.node===flower);if(f)return{type:'flower',f,node:flower}}const animalNode=eventTarget.closest?.('.creature');if(animalNode){const a=actors.find(a=>a.node===animalNode);if(a)return{type:'animal',a,node:animalNode}}}
  for(const c of [...$('clouds').children].map((node,i)=>({node,i}))){const b=c.node.getBoundingClientRect(),r=svg.getBoundingClientRect(),v=G.core.viewport(r.width,r.height),screen={x:r.x+v.ox+p.x*v.scale,y:r.y+v.oy+p.y*v.scale};if(screen.x>=b.left&&screen.x<=b.right&&screen.y>=b.top&&screen.y<=b.bottom)return{type:'cloud',id:c.i,node:c.node}}
  if(Math.hypot(p.x-1185,p.y-137)<86)return{type:'sun',node:$('sun')};
  const gate=config().portals.find(g=>Math.abs(p.x-g.x)<72&&Math.abs(p.y-g.y)<95);if(gate)return{type:'gate',id:gate.to,node:gates.querySelector(`[data-to="${gate.to}"]`)};
  if(ledger.current==='meadow'){if(fetch&&Math.hypot(p.x-fetch.ball.x,p.y-fetch.ball.y)<38)return{type:'ball',node:$('gardenBall')};if(Math.hypot(p.x-332,p.y-565)<63)return{type:'basket',node:$('basket')};const ap=[...harvest.states].find(([id,s])=>{const i=Number(id.slice(-1)),pos=s==='tree'?applePositions[i]:s==='ground'?groundSlots[i]:null;return pos&&Math.hypot(pos.x-p.x,pos.y-p.y)<39});if(ap)return{type:'apple',id:ap[0]};}
  const pool=actors.filter(a=>!a.exiting&&!a.hidden&&a.node.style.display!=='none').map(a=>({...a,x:a.x,y:a.y-a.size*.51,r:a.size*.36,ref:a})),near=G.core.pick(p,pool,Math.min(1,svg.getBoundingClientRect().width/1600));if(near)return{type:'animal',a:near.ref,node:near.ref.node};
  const f=flowers.find(f=>Math.hypot(p.x-f.nectar.x,p.y-f.nectar.y)<35);if(f)return{type:'flower',f,node:f.node};
  const w=config().water;if((p.x-w.x-w.w/2)**2/(w.w/2)**2+(p.y-w.y-w.h/2)**2/(w.h/2)**2<1)return{type:'stream'};return{type:'ground'};
 }
 function activate(h,p){if(paused||transition||rearm)return;G.audio.unlock();if(h.type==='gate'){switchScene(h.id);return}if(h.type==='portrait'){summon(h.id);return}if(h.type==='sun'){G.daynight.toggle(now);cue($('sun'));return}if(h.type==='apple'){applePick(h.id);return}if(h.type==='basket'){spillBasket();return}if(h.type==='animal'){react(h.a,true);return}if(h.type==='ball'){const dog=actors.find(a=>a.id==='dog');if(dog)react(dog);else summon('dog');return}if(h.type==='flower'){cue(h.f.node);flash(h.f.nectar);const elephant=actors.find(a=>a.id==='elephant');if(elephant&&!elephant.action)startWater(elephant,h.f.id);else if(ledger.current==='asian')startBees(h.f.id);else{const b=actors.find(a=>a.id==='butterfly'&&!a.flight&&a.flower!==h.f.id);if(b)butterflyFly(b,h.f.id)}return}
  if(h.type==='giraffe-browse'){summon('giraffe');return}if(h.type==='hive'){startBees();return}if(h.type==='fig'){dropFig(h.id);return}if(h.type==='figGround'){const bear=actors.find(a=>a.id==='bear');if(bear)react(bear);else summon('bear');return}if(h.type==='monkey-feed'){summon('monkey');return}if(h.type==='sloth-feed'){summon('sloth');return}if(h.type==='stream'){ripple(p,36);splash(p);const fish=actors.find(a=>a.id==='fish');if(fish)react(fish,true);return}if(h.type==='log'){const snail=$('forestSnail');cue(snail);ledger.state.snail=!ledger.state.snail;snail.setAttribute('transform',`translate(${ledger.state.snail?480:425} 674)`);return}if(h.type==='canopy-leaf'){dropLeaf(h.node);return}if(h.type==='broad-leaf'){broadLeaf(h.node);return}if(h.type==='fallen-leaf'){const id=h.node.dataset.leafId;ledger.state.flips[id]=!ledger.state.flips[id];h.node.firstElementChild?.setAttribute('transform',(h.node.firstElementChild.getAttribute('transform')||'').replace(/ scale\(1 -1\)/g,'')+(ledger.state.flips[id]?' scale(1 -1)':''));const squirrel=actors.find(a=>a.id==='squirrel');if(squirrel)react(squirrel);return}if(h.type==='fern'){cue(h.node);flash(p,'#becb99',3);return}
  if(ledger.current==='meadow'&&p.x<405&&p.y<500){cue($('appleTree'),'tree-touched');flash(p);return}if(ledger.current==='meadow'&&p.x>1240&&p.y<555){cue($('bananaTree'),'tree-touched');flash(p);return}const fruit=document.elementFromPoint(down?.clientX||0,down?.clientY||0)?.closest?.('[data-fruit]');if(fruit)cue(fruit);else plant(p);
 }
 function worldPoint(e){const r=svg.getBoundingClientRect(),v=G.core.viewport(r.width,r.height);return v.toWorld(e.clientX-r.x,e.clientY-r.y)}
 svg.addEventListener('pointerdown',e=>{if(e.button!==0&&e.pointerType!=='touch'||paused||transition||down)return;pointer=worldPoint(e);down={...pointer,clientX:e.clientX,clientY:e.clientY,id:e.pointerId};const h=hit(pointer,e.target);if(h.type==='broad-leaf'){down.leafNode=h.node;h.node.classList.add('leaf-held');$('forestLightPatch')?.setAttribute('cx',654)}if(h.type==='cloud'){const p=G.daynight.beginCloud(h.id,now);if(p)drag={i:h.id,initial:p,from:{...pointer},previous:p.previous,moved:false};}svg.setPointerCapture(e.pointerId);$('cursor').classList.add('pressed');G.audio.unlock();});
 svg.addEventListener('pointermove',e=>{if(down&&e.pointerId!==down.id)return;const p=worldPoint(e);pointer=p;$('cursor').style.left=e.clientX+'px';$('cursor').style.top=e.clientY+'px';$('cursor').style.opacity=1;
  if(drag){const dx=p.x-drag.from.x,dy=p.y-drag.from.y;if(Math.hypot(dx,dy)>7)drag.moved=true;G.daynight.moveCloud(drag.i,{dx:drag.initial.dx+dx,dy:drag.initial.dy+dy});return}
  if(paused||transition)return;const h=hit(p,e.target);if(rearm&&!down&&h.type!=='gate')rearm=false;if(hover?.node&&hover.node!==h.node)hover.node.classList.remove('hovered');h.node?.classList.add('hovered');hover=h;
  if(!down&&h.type==='canopy-leaf'&&hoverCool.take(h.node.dataset.leafId,now))dropLeaf(h.node);else if(!down&&h.type==='stream'&&hoverCool.take('ripples',now))ripple(p,20);else if(!down&&h.type==='flower'&&hoverCool.take(h.f.id,now)){cue(h.f.node);flash(h.f.nectar,'#edd4a7',2)}else if(!down&&h.type==='animal'&&hoverCool.take(h.a.key,now)){flash({x:p.x,y:p.y},'#e6d9b1',2)}else if(!down&&h.type==='ground'&&hoverCool.take('trail'+Math.floor(p.x/70),now))flash(p,'#d5d9aa',1);
 });
 svg.addEventListener('pointerup',e=>{if(!down||e.pointerId!==down.id)return;$('cursor').classList.remove('pressed');const start=down,p=worldPoint(e);down=null;if(start.leafNode){broadLeaf(start.leafNode);if(svg.hasPointerCapture(e.pointerId))svg.releasePointerCapture(e.pointerId);return}if(drag){G.daynight.endCloud(drag.i,now,drag.moved,drag.previous);drag=null;return}if(svg.hasPointerCapture(e.pointerId))svg.releasePointerCapture(e.pointerId);const target=document.elementFromPoint(e.clientX,e.clientY)||e.target;if(!transition&&!rearm&&Math.hypot(p.x-start.x,p.y-start.y)<24)activate(hit(p,target),p);});
