 function setPaused(value){paused=value;document.body.classList.toggle('paused',value);G.audio.setPaused(value);lastFrame=0;down?.leafNode?.classList.remove('leaf-held');if(drag)G.daynight.endCloud(drag.i,now,true,drag.previous);drag=null;down=null;}
 $('soundBtn').addEventListener('click',()=>{G.audio.setMuted(G.audio.ctx?!G.audio.muted:false);$('soundBtn').classList.toggle('muted',G.audio.muted);$('soundBtn').setAttribute('aria-pressed',String(G.audio.muted));if(!G.audio.muted)G.audio.unlock()});
