 document.addEventListener('keydown',e=>{if(e.ctrlKey&&e.shiftKey&&e.code==='KeyP'){e.preventDefault();$('parent').hidden=!$('parent').hidden;setPaused(!$('parent').hidden)}});
 for(const id of ['closeParent','resume'])$(id).addEventListener('click',()=>{$('parent').hidden=true;setPaused(false)});$('volume').addEventListener('input',e=>G.audio.setVolume(Number(e.target.value)));$('duration').addEventListener('input',e=>{limit=Number(e.target.value)*60000;elapsed=0});$('restart').addEventListener('click',()=>{$('rest').hidden=true;elapsed=0;setPaused(false)});
 document.addEventListener('visibilitychange',()=>{if(document.hidden)setPaused(true);else if($('parent').hidden&&$('rest').hidden)setPaused(false)});window.addEventListener('blur',()=>setPaused(true));window.addEventListener('focus',()=>{if($('parent').hidden&&$('rest').hidden)setPaused(false)});
 function tick(real){requestAnimationFrame(tick);if(!lastFrame)lastFrame=real;const dt=Math.min(45,real-lastFrame);lastFrame=real;if(paused)return;now+=dt;elapsed+=dt;if(limit&&elapsed>=limit){$('rest').hidden=false;setPaused(true);return}const q=G.daynight.render(now),next=q>.5?'night':'day';if(next!==time){time=next;svg.dataset.time=time;for(const a of actors){if(time==='day'&&a.id==='owl'&&a.flight){/* Finish the committed landing; do not drop out of the sky. */}if(time==='night'&&a.id==='butterfly')a.nextFlight=now+12000;}}
  ledger.advance(now);updateTransition();if(!transition){updateActors(dt);updateEffects(dt);const fireflies=$('forestFireflies'),patch=$('forestLightPatch');if(fireflies)fireflies.setAttribute('opacity',ledger.state.revealed?q*(.35+.2*Math.sin(now/2500)):0);if(patch){patch.setAttribute('fill',q>.5?'#c4d8de':'#f3e6b7');patch.setAttribute('opacity',.26*(1-G.daynight.sky.coverage*.75))}if(now>nextVisit&&config().guests.length){const busy=actors.some(a=>!a.resident&&config().guests.includes(a.id));if(!busy){summon(config().guests[nextVisitor++%config().guests.length],false);nextVisit=now+27000}else nextVisit=now+5000}}
  for(const n of $('animalTrail').children){n.classList.toggle('selected',actors.some(a=>a.id===n.dataset.summon&&!a.exiting));n.classList.toggle('requested',mainQueue===n.dataset.summon)}
 }
