 G.game={switchScene,summon,snapshot:()=>({scene:ledger.current,time,clock:now,epoch:ledger.epoch,actors:actors.map(a=>({id:a.id,key:a.key,x:a.x,y:a.y,flower:a.flower,hidden:!!a.hidden,state:a.exiting?'switch-out':a.flight?'flight':a.action?.kind||W.activity(a.id,animalTime(a))})),harvest:harvest.counts(),materials:ledger.state.materials.counts(),fetch:fetch?.state||null,bee:beeTrip?.phase||null,water:water?.phase||null,light:G.daynight.sky,paused,effects:fx.length,grown:ledger.state.grown.length}),get theme(){return{season:'spring',scene:ledger.current,time}},settings:{futureSeasons:['spring','summer','autumn','winter'],futureScenes:['meadow-rain','underwater']}};
